const SOURCES = {"australia":{"national":["business.gov.au","grants.gov.au","industry.gov.au","austrade.gov.au","ato.gov.au","arena.gov.au"],"regional":{"victoria":["business.vic.gov.au","vic.gov.au"],"new south wales":["nsw.gov.au","business.nsw.gov.au"],"queensland":["business.qld.gov.au","qld.gov.au"],"western australia":["wa.gov.au","smallbusiness.wa.gov.au"],"south australia":["sa.gov.au","business.sa.gov.au"],"tasmania":["business.tas.gov.au","tas.gov.au"],"northern territory":["nt.gov.au"],"australian capital territory":["act.gov.au"]}},"united states":{"national":["grants.gov","sbir.gov","sba.gov","energy.gov","nsf.gov"],"regional":{}},"united kingdom":{"national":["gov.uk","ukri.org","innovateuk.ukri.org"],"regional":{}},"canada":{"national":["canada.ca","ic.gc.ca","nrc-cnrc.gc.ca"],"regional":{}},"new zealand":{"national":["business.govt.nz","callaghaninnovation.govt.nz","nzte.govt.nz"],"regional":{}}};
const input = $('Tool Input').first().json;
const existingRows = $input.all().map((item) => item.json).filter((row) => row && row.profileId === 'default');
const existing = existingRows[0] ?? {};

const sessionId = typeof input.sessionId === 'string' ? input.sessionId.trim() : '';
const requestId = typeof input.requestId === 'string' ? input.requestId.trim() : '';
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let error = null;
if (!uuidPattern.test(sessionId) || !uuidPattern.test(requestId)) {
  error = { code: 'INVALID_SESSION', message: 'Saving a funding profile needs a valid conversation and request ID.' };
}

const text = (value, limit) => {
  const raw = typeof value === 'string' ? value.trim() : '';
  return raw.slice(0, limit ?? 200);
};
// Stripping every non-digit turns '$600k' into 600, which would then be
// checked against every turnover threshold for months without anyone
// noticing. Read the magnitude, and refuse anything ambiguous so the field
// stays empty and the agent asks again.
const number = (value) => {
  if (value === null || value === undefined || value === '') return null;
  const text = String(value).trim().toLowerCase().replace(/[\s,$£€]/g, '');
  const match = text.match(/^([0-9]*\.?[0-9]+)(k|m|bn|b)?$/);
  if (!match) return null;
  let parsed = Number(match[1]);
  if (!Number.isFinite(parsed) || parsed < 0) return null;
  if (match[2] === 'k') parsed *= 1000;
  else if (match[2] === 'm') parsed *= 1000000;
  else if (match[2] === 'b' || match[2] === 'bn') parsed *= 1000000000;
  return Math.round(parsed);
};
const yesNo = (value) => {
  const raw = text(value).toLowerCase();
  if (['yes', 'true', 'y'].includes(raw)) return 'yes';
  if (['no', 'false', 'n'].includes(raw)) return 'no';
  return '';
};
// A blank field means 'not mentioned this time', never 'erase what I said before'.
const keep = (next, previous) => (next === '' || next === null ? (previous ?? '') : next);

const merged = {
  legalName: keep(text(input.legalName), existing.legalName),
  entityType: keep(text(input.entityType, 60), existing.entityType),
  country: keep(text(input.country, 60), existing.country),
  region: keep(text(input.region, 60), existing.region),
  city: keep(text(input.city, 60), existing.city),
  industry: keep(text(input.industry, 120), existing.industry),
  industryCode: keep(text(input.industryCode, 20), existing.industryCode),
  headcount: keep(number(input.headcount), existing.headcount),
  annualRevenue: keep(number(input.annualRevenue), existing.annualRevenue),
  yearsTrading: keep(number(input.yearsTrading), existing.yearsTrading),
  registeredForGst: keep(yesNo(input.registeredForGst), existing.registeredForGst),
  doesRnd: keep(yesNo(input.doesRnd), existing.doesRnd),
  exports: keep(yesNo(input.exports), existing.exports),
  employsApprentices: keep(yesNo(input.employsApprentices), existing.employsApprentices),
  priorGrants: keep(text(input.priorGrants, 300), existing.priorGrants),
  interests: keep(text(input.interests, 300), existing.interests),
};

// Country and region decide which official sources the scan is allowed to
// read, so a profile without a country cannot produce a trustworthy scan.
if (!error && !merged.country) {
  error = { code: 'COUNTRY_REQUIRED', message: 'Ask the user which country the business is registered in before saving. Without it the scan cannot pick official sources.' };
}

// A model asked for a country writes AU, or Aus, or United States of America.
// Refusing those and reporting 'country not supported' sends the owner off to
// their platform administrator over a spelling.
const ALIASES = {
  au: 'australia', aus: 'australia', aud: 'australia',
  us: 'united states', usa: 'united states', 'u.s.': 'united states',
  'u.s.a.': 'united states', america: 'united states',
  'united states of america': 'united states',
  uk: 'united kingdom', gb: 'united kingdom', gbr: 'united kingdom',
  britain: 'united kingdom', 'great britain': 'united kingdom',
  england: 'united kingdom', scotland: 'united kingdom', wales: 'united kingdom',
  ca: 'canada', can: 'canada',
  nz: 'new zealand', nzl: 'new zealand', aotearoa: 'new zealand',
};
const rawCountry = merged.country.toLowerCase().replace(/\s+/g, ' ').trim();
const countryKey = ALIASES[rawCountry] ?? rawCountry;
const jurisdiction = SOURCES[countryKey] ?? null;
if (!error && !jurisdiction) {
  error = { code: 'COUNTRY_NOT_SUPPORTED', message: `This skill ships official source lists for Australia, the United States, the United Kingdom, Canada, and New Zealand, and did not recognise "${merged.country}". If the business is in one of those five, call this again with the country spelled out in full. Otherwise tell the user their country is not covered yet, and do not guess which websites are official.` };
}

let sourceDomains = { national: [], regional: [], local: [] };
if (jurisdiction) {
  const regionKey = merged.region.toLowerCase();
  sourceDomains = {
    national: jurisdiction.national,
    regional: jurisdiction.regional[regionKey] ?? [],
    local: [],
  };
}

const beats = ['national'];
if (sourceDomains.regional.length > 0) beats.push('regional');
beats.push('nongov');

const proposedInput = { sessionId, requestId, ...merged };
if (error) {
  return [{ json: { valid: false, sessionId, requestId, proposedInput, response: { ok: false, error } } }];
}

return [{ json: {
  valid: true,
  sessionId,
  requestId,
  proposedInput,
  profileSavedAt: new Date().toISOString(),
  ...merged,
  country: countryKey.replace(/\b[a-z]/g, (c) => c.toUpperCase()),
  sourceDomains: JSON.stringify(sourceDomains),
  beats: JSON.stringify(beats),
  regionalSourcesFound: sourceDomains.regional.length > 0,
} }];

const merged = $('Validate And Merge').first().json;
const saved = Number.isInteger($json.id) || $json.id !== undefined;
const missing = [];
if (!merged.headcount && merged.headcount !== 0) missing.push('how many people work there');
if (!merged.annualRevenue && merged.annualRevenue !== 0) missing.push('roughly what it turns over in a year');
if (!merged.entityType) missing.push('what kind of entity it is, such as a company or a sole trader');
if (!merged.region) missing.push('which state or region it is registered in');

return [{ json: { ...merged, response: {
  ok: true,
  saved: true,
  savedProfile: {
    legalName: merged.legalName, entityType: merged.entityType,
    country: merged.country, region: merged.region, city: merged.city,
    industry: merged.industry, headcount: merged.headcount,
    annualRevenue: merged.annualRevenue, yearsTrading: merged.yearsTrading,
    doesRnd: merged.doesRnd, exports: merged.exports,
  },
  beats: JSON.parse(merged.beats),
  regionalSourcesFound: merged.regionalSourcesFound,
  stillMissing: missing,
  message: missing.length
    ? 'Saved. Read the saved values back to the user, then ask for the missing ones — an eligibility verdict built on a guess stays wrong until someone notices.'
    : 'Saved. Read the saved values back to the user so they can correct anything you misheard.'
} } }];

const input = $('Validate And Merge').first().json;
const response = $json.response ?? { ok: false, error: { code: 'TOOL_FAILED', message: 'The tool did not return a result.' } };
return { json: {
  occurredAt: new Date().toISOString(),
  sessionId: input.sessionId,
  requestId: input.requestId,
  toolName: 'set_funding_profile',
  proposedInput: JSON.stringify(input.proposedInput ?? {}),
  result: JSON.stringify(response),
  error: response.ok === false ? String(response.error?.message ?? 'Tool failed') : '',
  response
} };

const prepared = $('Prepare Audit').item.json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) {
  response.auditWarning = 'The tool result could not be written to the local audit table.';
}
return { json: response };
